-- M6: reusable library documents, exact pins and immutable graphic artifacts.
-- No operational ORBAT hierarchy: units and parentUnitId remain canonical.
CREATE TABLE saved_symbol_families(id TEXT PRIMARY KEY,created_at TEXT NOT NULL);
CREATE TABLE saved_symbol_versions(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES saved_symbol_families(id),content_version INTEGER NOT NULL CHECK(content_version>0),status TEXT NOT NULL CHECK(status IN ('DRAFT','PUBLISHED')),document TEXT NOT NULL CHECK(json_valid(document)),content_hash TEXT NOT NULL CHECK(length(content_hash)=64),UNIQUE(family_id,id));
CREATE UNIQUE INDEX saved_symbol_version_labels ON saved_symbol_versions(family_id,json_extract(document,'$.versionLabel'));
CREATE INDEX saved_symbol_browse ON saved_symbol_versions(status,json_extract(document,'$.updatedAt'),json_extract(document,'$.name'));
CREATE TABLE saved_symbol_retirements(version_id TEXT PRIMARY KEY REFERENCES saved_symbol_versions(id),retired_at TEXT NOT NULL);
CREATE TRIGGER saved_symbol_create_draft BEFORE INSERT ON saved_symbol_versions WHEN NEW.status!='DRAFT' OR NEW.content_version!=1 BEGIN SELECT RAISE(ABORT,'Create a Draft library version first'); END;
CREATE TRIGGER saved_symbol_identity BEFORE UPDATE ON saved_symbol_versions WHEN NEW.id!=OLD.id OR NEW.family_id!=OLD.family_id OR NEW.content_version!=OLD.content_version+1 OR json_extract(NEW.document,'$.createdAt') IS NOT json_extract(OLD.document,'$.createdAt') OR json_extract(NEW.document,'$.parentVersionId') IS NOT json_extract(OLD.document,'$.parentVersionId') OR json_extract(NEW.document,'$.duplicatedFrom') IS NOT json_extract(OLD.document,'$.duplicatedFrom') BEGIN SELECT RAISE(ABORT,'Library identity/ancestry/counter mismatch'); END;
CREATE TRIGGER saved_symbol_frozen_update BEFORE UPDATE ON saved_symbol_versions WHEN OLD.status='PUBLISHED' BEGIN SELECT RAISE(ABORT,'Published library version is immutable'); END;
CREATE TRIGGER saved_symbol_frozen_delete BEFORE DELETE ON saved_symbol_versions WHEN OLD.status='PUBLISHED' BEGIN SELECT RAISE(ABORT,'Published library version is retained'); END;
CREATE TRIGGER saved_symbol_retirement_insert BEFORE INSERT ON saved_symbol_retirements WHEN (SELECT status FROM saved_symbol_versions WHERE id=NEW.version_id)!='PUBLISHED' BEGIN SELECT RAISE(ABORT,'Only a published library version may retire'); END;
CREATE TRIGGER saved_symbol_binding_insert BEFORE INSERT ON saved_symbol_versions WHEN NEW.id IS NOT json_extract(NEW.document,'$.versionId') OR NEW.family_id IS NOT json_extract(NEW.document,'$.familyId') OR NEW.status IS NOT json_extract(NEW.document,'$.status') OR NEW.content_version IS NOT json_extract(NEW.document,'$.contentVersion') BEGIN SELECT RAISE(ABORT,'Library row binding mismatch'); END;
CREATE TRIGGER saved_symbol_binding_update BEFORE UPDATE ON saved_symbol_versions WHEN NEW.id IS NOT json_extract(NEW.document,'$.versionId') OR NEW.family_id IS NOT json_extract(NEW.document,'$.familyId') OR NEW.status IS NOT json_extract(NEW.document,'$.status') OR NEW.content_version IS NOT json_extract(NEW.document,'$.contentVersion') BEGIN SELECT RAISE(ABORT,'Library row binding mismatch'); END;
CREATE TRIGGER immutable_saved_symbol_families_UPDATE BEFORE UPDATE ON saved_symbol_families BEGIN SELECT RAISE(ABORT,'Library history is immutable'); END;
CREATE TRIGGER immutable_saved_symbol_families_DELETE BEFORE DELETE ON saved_symbol_families BEGIN SELECT RAISE(ABORT,'Library history is immutable'); END;
CREATE TRIGGER immutable_saved_symbol_retirements_UPDATE BEFORE UPDATE ON saved_symbol_retirements BEGIN SELECT RAISE(ABORT,'Library history is immutable'); END;
CREATE TRIGGER immutable_saved_symbol_retirements_DELETE BEFORE DELETE ON saved_symbol_retirements BEGIN SELECT RAISE(ABORT,'Library history is immutable'); END;
CREATE TABLE saved_orbat_families(id TEXT PRIMARY KEY,created_at TEXT NOT NULL);
CREATE TABLE saved_orbat_versions(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES saved_orbat_families(id),content_version INTEGER NOT NULL CHECK(content_version>0),status TEXT NOT NULL CHECK(status IN ('DRAFT','PUBLISHED')),document TEXT NOT NULL CHECK(json_valid(document)),content_hash TEXT NOT NULL CHECK(length(content_hash)=64),UNIQUE(family_id,id));
CREATE UNIQUE INDEX saved_orbat_version_labels ON saved_orbat_versions(family_id,json_extract(document,'$.versionLabel'));
CREATE INDEX saved_orbat_browse ON saved_orbat_versions(status,json_extract(document,'$.updatedAt'),json_extract(document,'$.name'));
CREATE TABLE saved_orbat_retirements(version_id TEXT PRIMARY KEY REFERENCES saved_orbat_versions(id),retired_at TEXT NOT NULL);
CREATE TRIGGER saved_orbat_create_draft BEFORE INSERT ON saved_orbat_versions WHEN NEW.status!='DRAFT' OR NEW.content_version!=1 BEGIN SELECT RAISE(ABORT,'Create a Draft library version first'); END;
CREATE TRIGGER saved_orbat_identity BEFORE UPDATE ON saved_orbat_versions WHEN NEW.id!=OLD.id OR NEW.family_id!=OLD.family_id OR NEW.content_version!=OLD.content_version+1 OR json_extract(NEW.document,'$.createdAt') IS NOT json_extract(OLD.document,'$.createdAt') OR json_extract(NEW.document,'$.parentVersionId') IS NOT json_extract(OLD.document,'$.parentVersionId') OR json_extract(NEW.document,'$.duplicatedFrom') IS NOT json_extract(OLD.document,'$.duplicatedFrom') BEGIN SELECT RAISE(ABORT,'Library identity/ancestry/counter mismatch'); END;
CREATE TRIGGER saved_orbat_frozen_update BEFORE UPDATE ON saved_orbat_versions WHEN OLD.status='PUBLISHED' BEGIN SELECT RAISE(ABORT,'Published library version is immutable'); END;
CREATE TRIGGER saved_orbat_frozen_delete BEFORE DELETE ON saved_orbat_versions WHEN OLD.status='PUBLISHED' BEGIN SELECT RAISE(ABORT,'Published library version is retained'); END;
CREATE TRIGGER saved_orbat_retirement_insert BEFORE INSERT ON saved_orbat_retirements WHEN (SELECT status FROM saved_orbat_versions WHERE id=NEW.version_id)!='PUBLISHED' BEGIN SELECT RAISE(ABORT,'Only a published library version may retire'); END;
CREATE TRIGGER saved_orbat_binding_insert BEFORE INSERT ON saved_orbat_versions WHEN NEW.id IS NOT json_extract(NEW.document,'$.versionId') OR NEW.family_id IS NOT json_extract(NEW.document,'$.familyId') OR NEW.status IS NOT json_extract(NEW.document,'$.status') OR NEW.content_version IS NOT json_extract(NEW.document,'$.contentVersion') BEGIN SELECT RAISE(ABORT,'Library row binding mismatch'); END;
CREATE TRIGGER saved_orbat_binding_update BEFORE UPDATE ON saved_orbat_versions WHEN NEW.id IS NOT json_extract(NEW.document,'$.versionId') OR NEW.family_id IS NOT json_extract(NEW.document,'$.familyId') OR NEW.status IS NOT json_extract(NEW.document,'$.status') OR NEW.content_version IS NOT json_extract(NEW.document,'$.contentVersion') BEGIN SELECT RAISE(ABORT,'Library row binding mismatch'); END;
CREATE TRIGGER immutable_saved_orbat_families_UPDATE BEFORE UPDATE ON saved_orbat_families BEGIN SELECT RAISE(ABORT,'Library history is immutable'); END;
CREATE TRIGGER immutable_saved_orbat_families_DELETE BEFORE DELETE ON saved_orbat_families BEGIN SELECT RAISE(ABORT,'Library history is immutable'); END;
CREATE TRIGGER immutable_saved_orbat_retirements_UPDATE BEFORE UPDATE ON saved_orbat_retirements BEGIN SELECT RAISE(ABORT,'Library history is immutable'); END;
CREATE TRIGGER immutable_saved_orbat_retirements_DELETE BEFORE DELETE ON saved_orbat_retirements BEGIN SELECT RAISE(ABORT,'Library history is immutable'); END;
CREATE TABLE unit_profile_symbol_pins(owner_version_id TEXT PRIMARY KEY REFERENCES unit_profile_versions(id),symbol_family_id TEXT NOT NULL,symbol_version_id TEXT NOT NULL,content_hash TEXT NOT NULL,definition_hash TEXT NOT NULL,FOREIGN KEY(symbol_family_id,symbol_version_id) REFERENCES saved_symbol_versions(family_id,id));
CREATE TABLE saved_orbat_reference_pins(owner_version_id TEXT NOT NULL REFERENCES saved_orbat_versions(id),source_path TEXT NOT NULL,profile_family_id TEXT,profile_version_id TEXT,symbol_family_id TEXT,symbol_version_id TEXT,content_hash TEXT NOT NULL,PRIMARY KEY(owner_version_id,source_path),CHECK((profile_version_id IS NOT NULL)+(symbol_version_id IS NOT NULL)=1),CHECK((profile_family_id IS NULL)=(profile_version_id IS NULL)),CHECK((symbol_family_id IS NULL)=(symbol_version_id IS NULL)),FOREIGN KEY(profile_family_id,profile_version_id) REFERENCES unit_profile_versions(family_id,id),FOREIGN KEY(symbol_family_id,symbol_version_id) REFERENCES saved_symbol_versions(family_id,id));
CREATE TABLE operation_symbology_source_pins(operation_id TEXT NOT NULL,revision INTEGER NOT NULL,unit_id TEXT NOT NULL,source_path TEXT NOT NULL,profile_family_id TEXT,profile_version_id TEXT,symbol_family_id TEXT,symbol_version_id TEXT,orbat_family_id TEXT,orbat_version_id TEXT,content_hash TEXT NOT NULL,PRIMARY KEY(operation_id,revision,unit_id,source_path),CHECK((profile_version_id IS NOT NULL)+(symbol_version_id IS NOT NULL)+(orbat_version_id IS NOT NULL)=1),CHECK((profile_family_id IS NULL)=(profile_version_id IS NULL)),CHECK((symbol_family_id IS NULL)=(symbol_version_id IS NULL)),CHECK((orbat_family_id IS NULL)=(orbat_version_id IS NULL)),FOREIGN KEY(operation_id,revision) REFERENCES operation_revisions(operation_id,revision),FOREIGN KEY(profile_family_id,profile_version_id) REFERENCES unit_profile_versions(family_id,id),FOREIGN KEY(symbol_family_id,symbol_version_id) REFERENCES saved_symbol_versions(family_id,id),FOREIGN KEY(orbat_family_id,orbat_version_id) REFERENCES saved_orbat_versions(family_id,id));
CREATE TABLE operation_orbat_imports(operation_id TEXT NOT NULL,import_id TEXT NOT NULL,revision INTEGER NOT NULL,orbat_family_id TEXT NOT NULL,orbat_version_id TEXT NOT NULL,document TEXT NOT NULL CHECK(json_valid(document)),content_hash TEXT NOT NULL,PRIMARY KEY(operation_id,import_id),FOREIGN KEY(operation_id,revision) REFERENCES operation_revisions(operation_id,revision),FOREIGN KEY(orbat_family_id,orbat_version_id) REFERENCES saved_orbat_versions(family_id,id));
CREATE TABLE graphic_export_profile_versions(id TEXT NOT NULL,version INTEGER NOT NULL CHECK(version>0),document TEXT NOT NULL CHECK(json_valid(document)),content_hash TEXT NOT NULL,PRIMARY KEY(id,version));
CREATE TABLE graphic_exports(id TEXT PRIMARY KEY,symbol_version_id TEXT REFERENCES saved_symbol_versions(id),orbat_version_id TEXT REFERENCES saved_orbat_versions(id),operation_id TEXT,revision INTEGER,publication_id TEXT REFERENCES publications(id),profile_id TEXT NOT NULL,profile_version INTEGER NOT NULL,document TEXT NOT NULL CHECK(json_valid(document)),bytes BLOB NOT NULL,content_hash TEXT NOT NULL,CHECK((symbol_version_id IS NOT NULL)+(orbat_version_id IS NOT NULL)+(operation_id IS NOT NULL)=1),CHECK((operation_id IS NULL)=(revision IS NULL)),CHECK(publication_id IS NULL OR operation_id IS NOT NULL),FOREIGN KEY(operation_id,revision) REFERENCES operation_revisions(operation_id,revision),FOREIGN KEY(profile_id,profile_version) REFERENCES graphic_export_profile_versions(id,version));
CREATE INDEX graphic_exports_operation ON graphic_exports(operation_id,revision);
CREATE INDEX operation_symbology_sources ON operation_symbology_source_pins(operation_id,revision);
CREATE TRIGGER unit_profile_symbol_pins_insert BEFORE INSERT ON unit_profile_symbol_pins WHEN (SELECT status FROM unit_profile_versions WHERE id=NEW.owner_version_id)!='DRAFT' BEGIN SELECT RAISE(ABORT,'Published reference pins are immutable'); END;
CREATE TRIGGER unit_profile_symbol_pins_delete BEFORE DELETE ON unit_profile_symbol_pins WHEN (SELECT status FROM unit_profile_versions WHERE id=OLD.owner_version_id)!='DRAFT' BEGIN SELECT RAISE(ABORT,'Published reference pins are immutable'); END;
CREATE TRIGGER unit_profile_symbol_pins_update BEFORE UPDATE ON unit_profile_symbol_pins BEGIN SELECT RAISE(ABORT,'Replace Draft pins atomically'); END;
CREATE TRIGGER saved_orbat_reference_pins_insert BEFORE INSERT ON saved_orbat_reference_pins WHEN (SELECT status FROM saved_orbat_versions WHERE id=NEW.owner_version_id)!='DRAFT' BEGIN SELECT RAISE(ABORT,'Published reference pins are immutable'); END;
CREATE TRIGGER saved_orbat_reference_pins_delete BEFORE DELETE ON saved_orbat_reference_pins WHEN (SELECT status FROM saved_orbat_versions WHERE id=OLD.owner_version_id)!='DRAFT' BEGIN SELECT RAISE(ABORT,'Published reference pins are immutable'); END;
CREATE TRIGGER saved_orbat_reference_pins_update BEFORE UPDATE ON saved_orbat_reference_pins BEGIN SELECT RAISE(ABORT,'Replace Draft pins atomically'); END;
CREATE TRIGGER immutable_operation_symbology_source_pins_UPDATE BEFORE UPDATE ON operation_symbology_source_pins BEGIN SELECT RAISE(ABORT,'M6 history is immutable'); END;
CREATE TRIGGER immutable_operation_symbology_source_pins_DELETE BEFORE DELETE ON operation_symbology_source_pins BEGIN SELECT RAISE(ABORT,'M6 history is immutable'); END;
CREATE TRIGGER immutable_operation_orbat_imports_UPDATE BEFORE UPDATE ON operation_orbat_imports BEGIN SELECT RAISE(ABORT,'M6 history is immutable'); END;
CREATE TRIGGER immutable_operation_orbat_imports_DELETE BEFORE DELETE ON operation_orbat_imports BEGIN SELECT RAISE(ABORT,'M6 history is immutable'); END;
CREATE TRIGGER immutable_graphic_export_profile_versions_UPDATE BEFORE UPDATE ON graphic_export_profile_versions BEGIN SELECT RAISE(ABORT,'M6 history is immutable'); END;
CREATE TRIGGER immutable_graphic_export_profile_versions_DELETE BEFORE DELETE ON graphic_export_profile_versions BEGIN SELECT RAISE(ABORT,'M6 history is immutable'); END;
CREATE TRIGGER immutable_graphic_exports_UPDATE BEFORE UPDATE ON graphic_exports BEGIN SELECT RAISE(ABORT,'M6 history is immutable'); END;
CREATE TRIGGER immutable_graphic_exports_DELETE BEFORE DELETE ON graphic_exports BEGIN SELECT RAISE(ABORT,'M6 history is immutable'); END;
CREATE TRIGGER graphic_profile_binding BEFORE INSERT ON graphic_export_profile_versions WHEN NEW.id IS NOT json_extract(NEW.document,'$.id') OR NEW.version IS NOT json_extract(NEW.document,'$.version') BEGIN SELECT RAISE(ABORT,'Graphic profile binding mismatch'); END;
CREATE TRIGGER graphic_publication_binding BEFORE INSERT ON graphic_exports WHEN NEW.publication_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM publications WHERE id=NEW.publication_id AND operation_id=NEW.operation_id AND source_revision=NEW.revision) BEGIN SELECT RAISE(ABORT,'Graphic publication source mismatch'); END;
